/**
 * Mission datasets by id. Each room's fixture module builds a VISIBLE copy (the
 * evidence the learner queries; served at /api/missions/datasets/<id>) and a
 * SHADOW copy (same tables and shape, other values; never leaves the server,
 * the grader runs every learner query on it too).
 *
 * Built lazily and once per process: fixtures are generated by seeded code,
 * so the same id always yields the same rows on the client and the server.
 */
import type { MissionDataset } from "../types";
import { CLEAR_SKY } from "./clearSky";
import { LOOSE_THREAD } from "./looseThread";
import { RULE_AND_SIGN } from "./ruleAndSign";

export interface DatasetEntry { visible: () => MissionDataset; shadow: () => MissionDataset }

const REGISTRY: Record<string, DatasetEntry> = {
  "clear-sky": CLEAR_SKY,
  "loose-thread": LOOSE_THREAD,
  "rule-and-sign": RULE_AND_SIGN,
};

const built = new Map<string, { visible: MissionDataset; shadow: MissionDataset }>();

export function getDataset(id: string): { visible: MissionDataset; shadow: MissionDataset } | null {
  const hit = built.get(id);
  if (hit) return hit;
  const entry = Object.prototype.hasOwnProperty.call(REGISTRY, id) ? REGISTRY[id] : undefined;
  if (!entry) return null;
  const pair = { visible: entry.visible(), shadow: entry.shadow() };
  built.set(id, pair);
  return pair;
}

export function datasetIds(): string[] {
  return Object.keys(REGISTRY);
}
